<div class="admin-page-heading"><div><h1>ตั้งค่าเว็บไซต์</h1><p>ข้อมูลหน้าแรกและช่องทางติดต่อของหน่วยงาน</p></div></div><?php if($error): ?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif ?><form method="post" class="admin-panel form-panel" data-unsaved><?= csrf_field() ?><div class="form-grid"><?php foreach($fields as $key=>$label): ?><label><?= e($label) ?><?php if(in_array($key,['address','hero_description'],true)): ?><textarea name="<?= $key ?>" rows="3"><?= e($_POST[$key]??setting($key)) ?></textarea><?php else: ?><input name="<?= $key ?>" type="<?= str_ends_with($key,'_url')?'url':($key==='email'?'email':'text') ?>" value="<?= e($_POST[$key]??setting($key)) ?>"><?php endif ?></label><?php endforeach ?></div><label>ภาพเด่นหน้าแรก<select name="hero_media_id"><option value="0">ใช้ภาพประกอบตัวอย่าง</option><?php foreach(all("SELECT * FROM media WHERE mime LIKE 'image/%' ORDER BY id DESC") as $image): ?><option value="<?= $image['id'] ?>" <?= (int)($_POST['hero_media_id']??setting('hero_media_id'))===(int)$image['id']?'selected':'' ?>><?= e($image['name']) ?></option><?php endforeach ?></select><small>ภาพที่เลือกจะแสดงสาธารณะบนหน้าแรก</small></label><label class="checkbox"><input type="checkbox" name="demo_mode" <?= ($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['demo_mode']):setting('demo_mode')==='1')?'checked':'' ?>> แสดงป้ายเว็บไซต์ตัวอย่าง (ปิดเมื่อแทนเนื้อหาและภาพตัวอย่างครบแล้ว)</label><button class="button">บันทึกการตั้งค่า</button></form>
